// ── HOOKS ─────────────────────────────────────────────────────────────────────
function useInView(threshold = 0.2) {
  const ref = useRef(null);
  const [inView, setInView] = useState(false);
  useEffect(() => {
    const obs = new IntersectionObserver(([e]) => { if (e.isIntersecting) { setInView(true); obs.disconnect(); } }, { threshold });
    if (ref.current) obs.observe(ref.current);
    return () => obs.disconnect();
  }, [threshold]);
  return [ref, inView];
}

function useTypewriter(words, speed = 80, pause = 1800) {
  const [display, setDisplay] = useState("");
  const [wordIdx, setWordIdx] = useState(0);
  const [charIdx, setCharIdx] = useState(0);
  const [deleting, setDeleting] = useState(false);
  useEffect(() => {
    const current = words[wordIdx];
    let timeout;
    if (!deleting && charIdx <= current.length) {
      timeout = setTimeout(() => setCharIdx(c => c + 1), speed);
    } else if (!deleting && charIdx > current.length) {
      timeout = setTimeout(() => setDeleting(true), pause);
    } else if (deleting && charIdx >= 0) {
      timeout = setTimeout(() => setCharIdx(c => c - 1), speed / 2);
    } else {
      setDeleting(false);
      setWordIdx(i => (i + 1) % words.length);
    }
    setDisplay(current.slice(0, charIdx));
    return () => clearTimeout(timeout);
  }, [charIdx, deleting, wordIdx, words, speed, pause]);
  return display;
}

function useCountUp(target, inView, duration = 2000) {
  const [count, setCount] = useState(0);
  useEffect(() => {
    if (!inView) return;
    let start = 0;
    const step = target / (duration / 16);
    const timer = setInterval(() => {
      start += step;
      if (start >= target) { setCount(target); clearInterval(timer); }
      else setCount(Math.floor(start));
    }, 16);
    return () => clearInterval(timer);
  }, [inView, target, duration]);
  return count;
}

// ── PARTICLE CANVAS ───────────────────────────────────────────────────────────
function ParticleCanvas() {
  const canvasRef = useRef(null);
  const mouse = useRef({ x: -999, y: -999 });
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let width = canvas.width = window.innerWidth;
    let height = canvas.height = window.innerHeight;
    const particles = Array.from({ length: 90 }, () => ({
      x: Math.random() * width, y: Math.random() * height,
      r: Math.random() * 1.5 + 0.3,
      dx: (Math.random() - 0.5) * 0.4, dy: (Math.random() - 0.5) * 0.4,
      alpha: Math.random() * 0.6 + 0.2,
    }));
    let animId;
    const onMove = e => { mouse.current = { x: e.clientX, y: e.clientY }; };
    window.addEventListener("mousemove", onMove);
    function draw() {
      ctx.clearRect(0, 0, width, height);
      const mx = mouse.current.x, my = mouse.current.y;
      particles.forEach(p => {
        // Mouse repulsion
        const dx = p.x - mx, dy = p.y - my, dist = Math.hypot(dx, dy);
        if (dist < 100) { p.x += (dx / dist) * 1.5; p.y += (dy / dist) * 1.5; }
        ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(0,212,255,${p.alpha})`; ctx.fill();
        p.x += p.dx; p.y += p.dy;
        if (p.x < 0 || p.x > width) p.dx *= -1;
        if (p.y < 0 || p.y > height) p.dy *= -1;
      });
      for (let i = 0; i < particles.length; i++) {
        for (let j = i + 1; j < particles.length; j++) {
          const d = Math.hypot(particles[i].x - particles[j].x, particles[i].y - particles[j].y);
          if (d < 120) {
            ctx.beginPath(); ctx.moveTo(particles[i].x, particles[i].y); ctx.lineTo(particles[j].x, particles[j].y);
            ctx.strokeStyle = `rgba(0,102,255,${0.15 * (1 - d / 120)})`; ctx.lineWidth = 0.5; ctx.stroke();
          }
        }
      }
      animId = requestAnimationFrame(draw);
    }
    draw();
    const resize = () => { width = canvas.width = window.innerWidth; height = canvas.height = window.innerHeight; };
    window.addEventListener("resize", resize);
    return () => { cancelAnimationFrame(animId); window.removeEventListener("mousemove", onMove); window.removeEventListener("resize", resize); };
  }, []);
  return <canvas ref={canvasRef} style={{ position: "fixed", top: 0, left: 0, zIndex: 0, pointerEvents: "none", opacity: 0.7 }} />;
}

// ── 3D ROTATING TRIANGLE CANVAS ───────────────────────────────────────────────
function HeroCanvas() {
  const canvasRef = useRef(null);
  const mouse = useRef({ x: 0, y: 0 });
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    let W = canvas.width = canvas.offsetWidth;
    let H = canvas.height = canvas.offsetHeight;
    let angle = 0;
    let animId;
    const onMove = e => {
      const rect = canvas.getBoundingClientRect();
      mouse.current = { x: (e.clientX - rect.left - W / 2) / W, y: (e.clientY - rect.top - H / 2) / H };
    };
    window.addEventListener("mousemove", onMove);

    function project(x, y, z, cx, cy, fov = 400) {
      const scale = fov / (fov + z);
      return { x: cx + x * scale, y: cy + y * scale, scale };
    }

    function drawRing(cx, cy, radius, z, color, alpha, lineW = 1) {
      const pts = 64;
      ctx.beginPath();
      for (let i = 0; i <= pts; i++) {
        const a = (i / pts) * Math.PI * 2;
        const p = project(Math.cos(a) * radius, Math.sin(a) * radius, z, cx, cy);
        i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y);
      }
      ctx.strokeStyle = color; ctx.globalAlpha = alpha; ctx.lineWidth = lineW; ctx.stroke(); ctx.globalAlpha = 1;
    }

    function drawOrbit(cx, cy, rx, ry, tilt, color, dotAngle) {
      const pts = 64;
      ctx.beginPath();
      for (let i = 0; i <= pts; i++) {
        const a = (i / pts) * Math.PI * 2;
        const x = Math.cos(a) * rx;
        const y = Math.sin(a) * ry * Math.cos(tilt);
        const z = Math.sin(a) * ry * Math.sin(tilt);
        const p = project(x, y, z, cx, cy);
        i === 0 ? ctx.moveTo(p.x, p.y) : ctx.lineTo(p.x, p.y);
      }
      ctx.strokeStyle = color; ctx.globalAlpha = 0.25; ctx.lineWidth = 1; ctx.stroke(); ctx.globalAlpha = 1;
      // Dot on orbit
      const dx = Math.cos(dotAngle) * rx;
      const dy = Math.sin(dotAngle) * ry * Math.cos(tilt);
      const dz = Math.sin(dotAngle) * ry * Math.sin(tilt);
      const dp = project(dx, dy, dz, cx, cy);
      ctx.beginPath(); ctx.arc(dp.x, dp.y, 4 * dp.scale, 0, Math.PI * 2);
      ctx.fillStyle = color; ctx.globalAlpha = 0.9; ctx.fill(); ctx.globalAlpha = 1;
      // Glow
      const grd = ctx.createRadialGradient(dp.x, dp.y, 0, dp.x, dp.y, 10 * dp.scale);
      grd.addColorStop(0, color + "88"); grd.addColorStop(1, "transparent");
      ctx.beginPath(); ctx.arc(dp.x, dp.y, 10 * dp.scale, 0, Math.PI * 2);
      ctx.fillStyle = grd; ctx.fill();
    }

    function frame() {
      ctx.clearRect(0, 0, W, H);
      angle += 0.008;
      const cx = W / 2 + mouse.current.x * 30;
      const cy = H / 2 + mouse.current.y * 30;

      // Outer glow
      const grd = ctx.createRadialGradient(cx, cy, 0, cx, cy, 180);
      grd.addColorStop(0, "rgba(0,102,255,0.10)");
      grd.addColorStop(1, "transparent");
      ctx.fillStyle = grd; ctx.fillRect(0, 0, W, H);

      // Rings
      drawRing(cx, cy, 130, 0, "#00d4ff", 0.08, 1);
      drawRing(cx, cy, 160, 0, "#0066ff", 0.06, 1);

      // Orbits
      drawOrbit(cx, cy, 130, 130, Math.PI / 6, "#00d4ff", angle * 1.2);
      drawOrbit(cx, cy, 130, 130, Math.PI / 2.5, "#f5a623", angle * 0.7 + 2);
      drawOrbit(cx, cy, 130, 130, Math.PI / 1.4, "#00ffcc", angle * 0.9 + 4);

      // Central glow core
      const core = ctx.createRadialGradient(cx, cy, 0, cx, cy, 40);
      core.addColorStop(0, "rgba(0,212,255,0.35)");
      core.addColorStop(0.5, "rgba(0,102,255,0.15)");
      core.addColorStop(1, "transparent");
      ctx.fillStyle = core; ctx.beginPath(); ctx.arc(cx, cy, 40, 0, Math.PI * 2); ctx.fill();

      // Inner bright dot
      ctx.beginPath(); ctx.arc(cx, cy, 5, 0, Math.PI * 2);
      ctx.fillStyle = "#00d4ff"; ctx.globalAlpha = 0.9; ctx.fill(); ctx.globalAlpha = 1;

      // Scan line sweep
      const sweep = angle * 60 * (Math.PI / 180);
      const grad = ctx.createConicalGradient ? null : null;
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(sweep);
      const sweepGrd = ctx.createLinearGradient(0, 0, 160, 0);
      sweepGrd.addColorStop(0, "rgba(0,212,255,0.18)");
      sweepGrd.addColorStop(1, "transparent");
      ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, 160, -0.3, 0.3); ctx.closePath();
      ctx.fillStyle = sweepGrd; ctx.fill();
      ctx.restore();

      animId = requestAnimationFrame(frame);
    }
    frame();
    const resize = () => { W = canvas.width = canvas.offsetWidth; H = canvas.height = canvas.offsetHeight; };
    window.addEventListener("resize", resize);
    return () => { cancelAnimationFrame(animId); window.removeEventListener("mousemove", onMove); window.removeEventListener("resize", resize); };
  }, []);
  return <canvas ref={canvasRef} style={{ width: "100%", height: "100%", display: "block" }} />;
}

// ── PAGE LOADER ───────────────────────────────────────────────────────────────
function PageLoader({ onDone }) {
  const [progress, setProgress] = useState(0);
  const [fadeOut, setFadeOut] = useState(false);
  useEffect(() => {
    const t = setInterval(() => setProgress(p => { if (p >= 100) { clearInterval(t); return 100; } return p + 2; }), 25);
    return () => clearInterval(t);
  }, []);
  useEffect(() => {
    if (progress === 100) { setTimeout(() => setFadeOut(true), 400); setTimeout(onDone, 900); }
  }, [progress, onDone]);
  return (
    <div style={{
      position: "fixed", inset: 0, zIndex: 9999, background: "#020b18",
      display: "flex", flexDirection: "column", alignItems: "center", justifyContent: "center", gap: 32,
      opacity: fadeOut ? 0 : 1, transition: "opacity 0.5s ease", pointerEvents: fadeOut ? "none" : "all",
    }}>
      <div style={{ animation: "spin 2s linear infinite", filter: "drop-shadow(0 0 20px #00d4ff)" }}>
        <img src={LOGO_SRC} alt="logo" style={{ width: 120, height: 120, objectFit: "contain" }} />
      </div>
      <div style={{ fontFamily: "'Orbitron',monospace", fontSize: 13, letterSpacing: 4, color: "#00d4ff" }}>
        ELI's DiRecTriX
      </div>
      <div style={{ width: 260, height: 2, background: "rgba(0,212,255,0.15)", borderRadius: 2, overflow: "hidden" }}>
        <div style={{ height: "100%", width: `${progress}%`, background: "linear-gradient(90deg,#0066ff,#00d4ff,#f5a623)", transition: "width 0.03s linear", borderRadius: 2 }} />
      </div>
      <div style={{ fontFamily: "'Rajdhani',monospace", fontSize: 12, letterSpacing: 3, color: "#8ab0cc" }}>
        LOADING {progress}%
      </div>
    </div>
  );
}

