// ── WHATSAPP BUTTON ───────────────────────────────────────────────────────────
function WhatsAppButton() {
  const [hovered, setHovered] = useState(false);
  const [pulse, setPulse] = useState(true);
  useEffect(() => { setTimeout(() => setPulse(false), 4000); }, []);
  return (
    <a href="https://wa.me/233570865746" target="_blank" rel="noreferrer"
      onMouseEnter={() => setHovered(true)} onMouseLeave={() => setHovered(false)}
      style={{
        position: "fixed", bottom: 28, right: 28, zIndex: 200,
        width: 58, height: 58, borderRadius: "50%",
        background: "linear-gradient(135deg,#25d366,#128c7e)",
        display: "flex", alignItems: "center", justifyContent: "center",
        fontSize: 26, textDecoration: "none",
        boxShadow: hovered ? "0 8px 32px rgba(37,211,102,0.6)" : "0 4px 20px rgba(37,211,102,0.4)",
        transform: hovered ? "scale(1.12)" : "scale(1)",
        transition: "all 0.3s cubic-bezier(0.16,1,0.3,1)",
      }}>
      💬
      {pulse && <span style={{ position: "absolute", inset: -4, borderRadius: "50%", border: "2px solid #25d366", animation: "ping 1.5s cubic-bezier(0,0,0.2,1) infinite" }} />}
      {hovered && (
        <div style={{ position: "absolute", right: 68, background: "rgba(6,21,40,0.95)", border: "1px solid rgba(37,211,102,0.3)", borderRadius: 8, padding: "8px 14px", whiteSpace: "nowrap", fontFamily: "'Rajdhani',sans-serif", fontSize: 13, color: "#fff", letterSpacing: 1 }}>
          Chat on WhatsApp
        </div>
      )}
    </a>
  );
}

